import { useReducer } from 'react';
type State = { status: 'idle' | 'running'; step: number };
type Action = { type: 'start' | 'next' | 'reset' };
const initial: State = { status: 'idle', step: 0 };
export function reducer(state: State, action: Action): State {
  switch (action.type) {
    case 'start': return { status: 'running', step: 0 };
    case 'next': return state.status === 'running' ? { ...state, step: state.step + 1 } : state;
    case 'reset': return initial;
    default: return state;
  }
}
export default function App() {
  const [state, dispatch] = useReducer(reducer, initial);
  return <main><p>{state.status}: {state.step}</p>{(['start', 'next', 'reset'] as const).map(type => <button key={type} onClick={() => dispatch({ type })}>{type}</button>)}</main>;
}

