import { useState } from 'react';
type Product = { id: number; name: string };
const notebook: Product = { id: 1, name: 'Notebook' };
function Catalog({ onAdd }: { onAdd: (product: Product) => void }) {
  return <button onClick={() => onAdd(notebook)}>Add notebook</button>;
}
function Cart({ items, onRemove }: { items: Product[]; onRemove: (id: number) => void }) {
  return <ul>{items.map(item => <li key={item.id}>{item.name}<button onClick={() => onRemove(item.id)}>Remove</button></li>)}</ul>;
}
export default function App() {
  const [items, setItems] = useState<Product[]>([]);
  function add(product: Product) { setItems(previous => previous.some(item => item.id === product.id) ? previous : [...previous, product]); }
  function remove(id: number) { setItems(previous => previous.filter(item => item.id !== id)); }
  return <main><Catalog onAdd={add} /><Cart items={items} onRemove={remove} /></main>;
}

