import { configureStore, createSlice, type PayloadAction } from '@reduxjs/toolkit';
import { Provider, useDispatch, useSelector } from 'react-redux';
import { QueryClient, QueryClientProvider, useQuery } from '@tanstack/react-query';
const favorites = createSlice({
  name: 'favorites', initialState: [] as number[],
  reducers: { toggle(state, action: PayloadAction<number>) {
    const id = action.payload;
    return state.includes(id) ? state.filter(value => value !== id) : [...state, id];
  } },
});
const store = configureStore({ reducer: { favorites: favorites.reducer } });
type RootState = ReturnType<typeof store.getState>;
const queryClient = new QueryClient();
const demoProducts = [{ id: 1, name: 'Notebook' }, { id: 2, name: 'Pencil' }];
function Products() {
  const { data, isPending, error } = useQuery({ queryKey: ['demo-products'], queryFn: async () => demoProducts });
  const selected = useSelector((state: RootState) => state.favorites);
  const dispatch = useDispatch();
  if (isPending) return <p>Loading local example...</p>;
  if (error) return <p role="alert">Example could not load</p>;
  return <ul>{data.map(product => <li key={product.id}>{product.name}
    <button aria-pressed={selected.includes(product.id)} onClick={() => dispatch(favorites.actions.toggle(product.id))}>Favorite</button>
  </li>)}</ul>;
}
export default function App() {
  return <Provider store={store}><QueryClientProvider client={queryClient}><Products /></QueryClientProvider></Provider>;
}

